// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"pt-BR","term":"Máxima histórica (ATH)","aka":["ATH","all-time high","topo histórico"],"short":"Máxima histórica (ATH, all-time high) é o maior preço que um ativo já atingiu desde que começou a ser negociado.","body":[["Quando um ativo supera a máxima anterior, ninguém que comprou antes está no prejuízo, porque não há vendedores esperando sair no zero a zero. Isso pode facilitar movimentos rápidos para cima. Por outro lado, o ATH também atrai ",["realização de lucro","take-profit"]," e muita gente comprando por ",["FOMO","fomo"],"."],["O ATH é diferente entre corretoras e pares. O ",["bitcoin","bitcoin"]," pode marcar uma máxima em dólar sem marcar em reais, ou o contrário, dependendo do câmbio. E pavios rápidos numa corretora com pouca ",["liquidez","liquidity"]," podem mostrar uma máxima que outras não registraram."],["Também existe a mínima histórica, ATL (all-time low). A distância do ",["preço atual","last-price"]," em relação ao ATH ajuda a entender o tamanho de uma queda: um token 90% abaixo do ATH precisa subir 10 vezes para voltar ao topo."]],"example":"Imagine que o ATH de um token é US$ 8 e hoje ele está a US$ 2, ou seja, 75% abaixo da máxima. Para voltar a US$ 8, ele precisa subir 300%, multiplicando por 4. Outro token, que está apenas 20% abaixo do ATH, a US$ 40 com máxima de US$ 50, precisa subir só 25% para igualar o topo. Queda e recuperação não são simétricas.","mistakes":["Achar que um token 90% abaixo do ATH está barato e vai necessariamente voltar ao topo.","Comprar com alavancagem no rompimento de um ATH sem plano para uma reversão.","Comparar ATH em reais com ATH em dólar sem considerar o câmbio."],"faq":[{"q":"O que é ATH e ATL?","a":"ATH é a máxima histórica, o maior preço já registrado. ATL é a mínima histórica, o menor preço já registrado."},{"q":"É ruim comprar na máxima histórica?","a":"Não necessariamente, mas o risco de correção perto do topo costuma ser alto. Muitos investidores compram aos poucos para não depender de um único preço de entrada."}],"title":"O que é ATH (máxima histórica) em cripto?","description":"Entenda o que é ATH, por que o rompimento de uma máxima histórica importa e como calcular quanto falta para voltar ao topo.","related":[["bull-market","Mercado de alta (bull market)","Mercado de alta (bull market) é um período prolongado em que os preços sobem de forma geral, com topos e fundos cada vez mais altos e otimismo crescente entre os investidores."],["fomo","FOMO (medo de ficar de fora)","FOMO (fear of missing out, ou medo de ficar de fora) é a ansiedade de perder uma alta que leva o investidor a comprar por impulso, geralmente depois que o preço já subiu muito."],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos."],["support-and-resistance","Suporte e resistência","Suporte e resistência são faixas de preço onde o mercado já parou várias vezes: o suporte é onde a queda costuma encontrar compradores, e a resistência é onde a alta costuma encontrar vendedores."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"pt-BR","term":"Futuros com margem em moeda (inversos)","aka":["futuros inversos","coin-margined","COIN-M","contrato inverso"],"short":"Futuros com margem em moeda, ou inversos, são contratos em que a margem, o lucro e o prejuízo são calculados na própria criptomoeda, como BTC, e não em uma stablecoin.","body":[["Em um contrato BTCUSD inverso, você deposita ",["BTC","bitcoin"]," como margem e recebe ou paga resultados em BTC. O tamanho do contrato costuma ser definido em dólares, por exemplo 100 dólares por contrato, e o resultado em BTC depende do preço de entrada e de saída."],["Isso cria um efeito duplo. Se você está ",["comprado","long-and-short"]," e o preço sobe, ganha mais BTC e cada BTC vale mais. Se o preço cai, perde BTC e cada BTC vale menos. Por isso o lucro em dólares não é linear. Em compensação, mineradores e quem já guarda BTC podem ",["fazer hedge","hedging"]," sem ",["converter","instant-convert"]," para ",["stablecoin","stablecoin"],"."],"Corretoras como Binance, OKX, Bybit e Bitget oferecem as duas famílias de contrato. Os nomes variam (COIN-M, inverso, margem em moeda), assim como o tamanho do contrato e as regras de margem."],"example":"Suponha que você tenha 1 BTC e o preço seja 50.000 dólares. Para se proteger, abre um short inverso de 50.000 dólares (500 contratos de 100 dólares). Se BTC cair para 40.000, o short rende 50.000 dividido por 40.000 menos 50.000 dividido por 50.000, ou seja, 1,25 menos 1, que dá 0,25 BTC. Você fica com 1,25 BTC, que a 40.000 valem 50.000 dólares, protegendo o valor em dólar.","mistakes":["Esquecer que a margem em BTC perde valor junto com o preço quando você está comprado.","Calcular o lucro de um contrato inverso como se fosse linear.","Confundir o tamanho em contratos com o tamanho em moedas."],"faq":[{"q":"Qual a diferença entre futuros inversos e lineares?","a":"No inverso a margem e o resultado são na própria moeda, como BTC. No linear são em uma stablecoin, como USDT ou USDC, e o cálculo é mais direto."},{"q":"Para quem servem os futuros com margem em moeda?","a":"São úteis para quem já tem a moeda e quer fazer hedge ou operar sem converter para stablecoin, como mineradores e holders de longo prazo."}],"title":"O que são futuros inversos (margem em moeda)?","description":"Entenda como funcionam os futuros com margem em moeda (COIN-M), o cálculo não linear do lucro e quando eles são usados para hedge.","related":[["usdt-margined-futures","Futuros com margem em USDT (lineares)","Futuros com margem em USDT, ou lineares, são contratos em que a margem, o lucro e o prejuízo são calculados em USDT, então o resultado cresce de forma linear com a variação do preço."],["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["unrealized-pnl","Lucro/prejuízo não realizado (PnL não realizado)","Lucro ou prejuízo não realizado (PnL não realizado) é o resultado que uma posição aberta teria se fosse fechada agora, calculado pela diferença entre o preço de entrada e o preço atual de referência."],["hedging","Hedge (proteção)","Hedge é abrir uma posição que ganha quando a sua posição principal perde, para reduzir o impacto de movimentos de preço contra você, em troca de abrir mão de parte do ganho."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: você não está comprando a mesma coisa"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"pt-BR","term":"Hedge (proteção)","aka":["hedge","hedging","proteção de carteira","fazer hedge"],"short":"Hedge é abrir uma posição que ganha quando a sua posição principal perde, para reduzir o impacto de movimentos de preço contra você, em troca de abrir mão de parte do ganho.","body":["No cripto, a forma mais comum é ter a moeda no spot e abrir um short em futuros do mesmo ativo. Se o preço cai, o short compensa a perda do spot. Se sobe, o spot ganha e o short perde. Também é possível fazer hedge com opções, comprando uma put, que funciona como um seguro com custo definido.","O hedge pode ser total, cobrindo 100% da exposição, ou parcial, cobrindo só uma parte. Ele tem custos: taxas, funding nos perpétuos, prêmio nas opções e margem que fica presa. E nem sempre é perfeito: um hedge com outra moeda, por exemplo, pode falhar se os preços se moverem de forma diferente.","Mineradores, empresas que recebem em cripto e holders de longo prazo usam hedge para atravessar períodos de incerteza sem vender a moeda. Para traders, ele serve para reduzir o risco de uma carteira antes de um evento importante."],"example":["Você tem 10 ",["ETH","ethereum"]," comprados a 3.000 ",["USDT","usdt"]," e quer se proteger por um mês. Abre um short de 5 ETH no ",["perpétuo","perpetual-futures"],", cobrindo 50%. Se ETH cair para 2.600, o spot perde 4.000 USDT e o short ganha 2.000, perda líquida de 2.000. Se ETH subir para 3.400, o spot ganha 4.000 e o short perde 2.000, ganho líquido de 2.000, sem contar taxas e funding."],"mistakes":["Esquecer o custo de funding de um short mantido por muito tempo.","Usar alavancagem alta no short de hedge e ser liquidado numa alta, perdendo a proteção.","Fechar o hedge e esquecer que a carteira voltou a ficar totalmente exposta."],"faq":[{"q":"Como fazer hedge de bitcoin?","a":"Uma forma comum é abrir um short em futuros de BTC do mesmo tamanho, ou de parte, do que você tem no spot. Outra é comprar opções de venda."},{"q":"Hedge elimina o risco?","a":"Reduz o risco de preço, mas cria outros, como custos, risco de liquidação do short e diferenças entre os instrumentos."}],"title":"O que é hedge em cripto? Como se proteger","description":"Entenda o que é hedge em cripto, como usar short em futuros ou opções para proteger a carteira e quais custos isso envolve.","related":[["short-selling","Venda a descoberto (short selling)","Venda a descoberto (short selling) é vender um ativo que você não possui, por empréstimo ou por contrato futuro, para recomprá-lo depois mais barato e lucrar com a queda do preço."],["perpetual-futures","Futuros perpétuos","Futuros perpétuos são contratos futuros sem data de vencimento, que acompanham o preço à vista do ativo por meio de uma taxa de financiamento paga periodicamente entre comprados e vendidos."],["options","Opções de cripto","Opções de cripto são contratos que dão ao comprador o direito, mas não a obrigação, de comprar (call) ou vender (put) um ativo a um preço definido, o strike, até ou em uma data de vencimento."],["portfolio-margin","Margem de portfólio","Margem de portfólio é um modo de cálculo em que a exigência de margem considera o risco líquido de todas as posições juntas, permitindo menos margem quando elas se compensam."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: você não está comprando a mesma coisa"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"pt-BR","term":"Opções de cripto","aka":["opções","options","call","put"],"short":"Opções de cripto são contratos que dão ao comprador o direito, mas não a obrigação, de comprar (call) ou vender (put) um ativo a um preço definido, o strike, até ou em uma data de vencimento.","body":["Quem compra uma opção paga um prêmio. Na call, ganha se o preço subir acima do strike mais o prêmio. Na put, ganha se cair abaixo do strike menos o prêmio. A perda máxima do comprador é o prêmio pago. Quem vende a opção recebe o prêmio e assume a obrigação, com risco que pode ser bem maior.",["O preço da opção depende da distância entre o ",["preço atual","last-price"]," e o strike, do tempo até o vencimento e da ",["volatilidade","volatility"]," implícita. Quanto mais volátil o mercado e mais longo o prazo, mais caro o prêmio. Com o passar do tempo, a opção perde valor se o preço não se mover a favor."],["No cripto, as opções de ",["BTC","bitcoin"]," e ",["ETH","ethereum"]," são negociadas em plataformas como Deribit, OKX, Bybit e Binance, em geral no estilo europeu, exercidas só no vencimento e liquidadas em dinheiro. Produtos como o ",["investimento duplo","dual-investment"]," usam opções por trás, vendendo uma opção em seu nome."]],"example":["Suponha BTC a 60.000 ",["USDT","usdt"],". Você compra uma call de 0,1 BTC com strike 65.000 e vencimento em 30 dias, pagando 150 USDT de prêmio. No vencimento, se BTC estiver a 70.000, a opção vale 0,1 vezes 5.000, ou 500 USDT, lucro de 350. Se estiver a 66.500, vale 150 e você empata. Abaixo de 65.000, a opção vence sem valor e você perde só os 150."],"mistakes":["Comprar opções muito fora do dinheiro só porque o prêmio é barato.","Vender opções sem entender que a perda pode ser muito maior que o prêmio recebido.","Ignorar que a opção perde valor com o tempo, mesmo que o preço fique parado."],"faq":[{"q":"Qual a diferença entre opções e futuros?","a":"No futuro, os dois lados têm obrigação e o resultado acompanha o preço linearmente. Na opção, o comprador tem um direito, paga um prêmio e sua perda máxima é limitada a ele."},{"q":"O que é uma call e uma put?","a":"Call é o direito de comprar a um preço definido e ganha com a alta. Put é o direito de vender a um preço definido e ganha com a queda."}],"title":"O que são opções de cripto? Call e put explicados","description":"Entenda o que são opções de cripto, como funcionam call, put, strike e prêmio, e qual o risco de comprar e de vender opções.","related":[["futures-contract","Contrato futuro","Um contrato futuro é um acordo para comprar ou vender um ativo a um preço definido, com liquidação em uma data futura ou, no caso dos perpétuos, sem data de vencimento."],["hedging","Hedge (proteção)","Hedge é abrir uma posição que ganha quando a sua posição principal perde, para reduzir o impacto de movimentos de preço contra você, em troca de abrir mão de parte do ganho."],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos."],["dual-investment","Investimento duplo (dual investment)","Investimento duplo é um produto estruturado de corretora em que você deposita uma cripto ou stablecoin, escolhe um preço-alvo e uma data, e no vencimento recebe juros mais o capital na moeda original ou na outra moeda, conforme o preço final."]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"pt-BR","term":"Carteira custodial","aka":["custodial wallet","carteira custodiada","custódia na corretora"],"short":"Carteira custodial é uma carteira em que uma empresa, geralmente uma corretora, guarda as chaves privadas dos seus criptoativos e movimenta os fundos em seu nome.","body":[["Quando você deposita na conta de uma corretora, como Binance, OKX ou Mercado ",["Bitcoin","bitcoin"],", os ativos passam a ficar em carteiras controladas pela empresa. Você vê um saldo no aplicativo, mas quem assina as transações na ",["blockchain","blockchain"]," é a corretora. Se você esquecer a senha, pode recuperar o acesso pelo suporte, o que não acontece em uma ",["carteira de autocustódia","non-custodial-wallet"],"."],"A praticidade tem um preço: você depende da segurança, da solvência e das regras da empresa. Saques podem ser pausados, contas podem ser bloqueadas por verificação e, em caso de falência, os clientes podem ter dificuldade para recuperar os fundos. Provas de reservas ajudam a verificar se a corretora tem os ativos que diz ter, mas não mostram todo o passivo.",["Muitos traders mantêm na corretora só o que precisam para negociar e guardam o restante em autocustódia. Regras de ",["proteção","hedging"]," ao cliente e segregação de ativos variam por país e por empresa."]],"example":["Suponha que você tenha 1.500 ",["USDT","usdt"]," e 0,5 ",["ETH","ethereum"],". Você deixa 400 USDT na corretora para operar e move os 1.100 USDT restantes e o ETH para uma carteira de autocustódia. Se a corretora suspender saques por alguns dias, só 400 USDT, cerca de 27% do valor em stablecoin, ficam travados, e você continua com controle total do resto."],"mistakes":["Deixar todo o patrimônio em uma única corretora por conveniência.","Não ativar autenticação em dois fatores e lista de endereços permitidos para saque.","Achar que a corretora sempre reembolsa perdas causadas por golpes ou acesso indevido."],"faq":[{"q":"É seguro deixar cripto na corretora?","a":"Grandes corretoras investem muito em segurança, mas você assume o risco da empresa. Diversificar e manter em autocustódia o que não está sendo negociado reduz essa dependência."},{"q":"Qual a diferença entre carteira custodial e não custodial?","a":"Na custodial a empresa controla as chaves privadas. Na não custodial, você controla as chaves e a frase de recuperação e é o único responsável por elas."}],"title":"O que é carteira custodial? Prós e contras","description":"Entenda o que é uma carteira custodial, como funciona a custódia em corretoras e quais riscos considerar ao deixar cripto nelas.","related":[["non-custodial-wallet","Carteira não custodial (autocustódia)","Uma carteira não custodial é uma carteira de cripto em que só você controla a chave privada e a frase de recuperação, sem depender de uma corretora ou empresa para guardar ou liberar seus fundos."],["centralized-exchange","Corretora centralizada (CEX)","Corretora centralizada (CEX) é uma empresa que intermedeia a compra e venda de criptomoedas, guarda os ativos dos clientes e opera seu próprio livro de ofertas, como Binance, OKX, Bybit ou Mercado Bitcoin."],["proof-of-reserves","Prova de reservas (proof of reserves)","A prova de reservas (proof of reserves) é um método que uma corretora usa para demonstrar que mantém em carteiras próprias ativos suficientes para cobrir os saldos dos clientes."],["crypto-wallet","Carteira de criptomoedas","Carteira de criptomoedas é um aplicativo, dispositivo ou serviço que guarda as chaves privadas que dão acesso aos seus criptoativos e permite enviar, receber e assinar transações."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Onde estão minhas moedas? Corretora vs carteira"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"pt-BR","term":"Análise on-chain","aka":["análise on-chain","on-chain analysis","métricas on-chain","dados on-chain"],"short":"Análise on-chain é o estudo dos dados públicos registrados em uma blockchain, como transações, saldos de carteiras e fluxos para corretoras, para entender o comportamento de investidores e da rede.","body":[["Como blockchains como ",["Bitcoin","bitcoin"]," e ",["Ethereum","ethereum"]," são públicas, qualquer pessoa pode ver quanto foi movimentado, entre quais endereços e quando. Ferramentas de análise agrupam esses dados em métricas: ",["endereços ativos","active-addresses"],", fluxo líquido para corretoras, movimentação de baleias, idade das moedas que estão sendo gastas, taxas pagas e ",["hash rate","hash-rate"],"."],"Para quem negocia, a análise on-chain complementa a análise técnica (gráfico) e a fundamentalista. Por exemplo, grandes entradas de BTC em corretoras podem indicar intenção de venda, enquanto saídas fortes podem indicar que investidores estão levando moedas para custódia própria. Nada disso é sinal garantido; são pistas que precisam de contexto.","Um limite importante: os dados mostram endereços, não pessoas. Um único endereço de corretora pode representar milhões de clientes, e transferências internas entre carteiras da mesma empresa podem parecer grandes movimentos. Cada provedor também rotula endereços de forma diferente, então números podem variar entre ferramentas."],"example":"Suponha que, em uma semana, 40.000 BTC entrem em corretoras e 25.000 BTC saiam. O fluxo líquido é de 15.000 BTC entrando. Se ao mesmo tempo o número de endereços ativos cair 10%, um analista pode ler isso como menor uso da rede somado a mais moedas disponíveis para venda, e então buscar confirmação no gráfico e no volume.","mistakes":["Tomar uma única métrica on-chain como sinal de compra ou venda sem olhar o contexto.","Confundir transferências internas de uma corretora com compras ou vendas reais.","Comparar números de ferramentas diferentes sem saber como cada uma rotula os endereços."],"faq":[{"q":"Análise on-chain funciona para qualquer criptomoeda?","a":"Funciona melhor em redes públicas com muitos dados, como Bitcoin e Ethereum. Moedas com foco em privacidade ou pouco uso oferecem pouca informação útil."},{"q":"Qual a diferença entre análise on-chain e análise técnica?","a":"A técnica estuda preço e volume nos gráficos das corretoras. A on-chain estuda o que acontece dentro da própria blockchain, como transferências, saldos e uso da rede."}],"title":"O que é análise on-chain? Como ler dados da blockchain","description":"Entenda o que é análise on-chain, quais métricas os traders acompanham e quais são os limites desses dados públicos.","related":[["exchange-netflow","Fluxo de entrada e saída das corretoras (netflow)","O fluxo de entrada e saída das corretoras mede quanta cripto está sendo depositada e sacada das corretoras centralizadas, e o netflow é a diferença entre as entradas e as saídas num período."],["whale","Baleia (whale)","Baleia (whale) é como o mercado chama uma pessoa ou entidade que detém uma quantidade muito grande de uma criptomoeda, capaz de mexer no preço quando compra ou vende."],["active-addresses","Endereços ativos","Endereços ativos são a quantidade de endereços únicos que enviaram ou receberam transações em uma blockchain dentro de um período, como um dia ou um mês, e servem como medida aproximada de uso da rede."],["block-explorer","Explorador de blocos (block explorer)","Um explorador de blocos é um site de busca que mostra os dados públicos de uma blockchain, permitindo consultar transações, endereços, blocos e saldos a partir de um hash ou de um endereço."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"pt-BR","term":"Robô de grid (grid trading bot)","aka":["grid bot","robô de grid","grid trading","bot de grade"],"short":"Um robô de grid é uma ferramenta automática que distribui várias ordens de compra e venda em intervalos fixos dentro de uma faixa de preço, comprando nas quedas e vendendo nas altas para lucrar com a oscilação.","body":[["Você define o preço mínimo, o preço máximo, o número de níveis da grade e o capital. O robô coloca ordens limitadas de compra abaixo do ",["preço atual","last-price"]," e de venda acima. Cada vez que o preço cai e sobe de novo entre dois níveis, uma compra e uma venda se completam e o robô embolsa a diferença, menos as taxas."],["Funciona melhor em mercados laterais e voláteis. Se o preço sai da faixa para baixo, o robô termina com todo o capital no ativo, que agora vale menos. Se sai para cima, termina todo em ",["USDT","usdt"]," e deixa de aproveitar a alta. Há também versões em futuros, com ",["alavancagem","leverage"],", que acrescentam risco de ",["liquidação","liquidation"],"."],"Muitas corretoras oferecem robôs de grid gratuitos, mas cobram as taxas normais de negociação em cada ordem. Grades muito apertadas geram muitas operações com lucro pequeno, que pode ser engolido pelas taxas."],"example":["Suponha um grid de ",["ETH","ethereum"]," entre 2.000 e 2.400 USDT dividido em 8 intervalos de 50 USDT, com 0,1 ETH por nível. Cada ciclo de compra a 2.100 e venda a 2.150 rende 5 USDT brutos. Com taxa de 0,1% por ordem, paga cerca de 0,21 + 0,22 USDT e fica com uns 4,57. Se o ETH cair para 1.800, o robô fica ",["comprado","long-and-short"]," e acumula prejuízo não realizado."],"mistakes":["Configurar a faixa estreita demais e ver o preço sair dela no primeiro movimento forte.","Ignorar as taxas por ordem ao escolher um número alto de níveis.","Usar grid de futuros com alavancagem sem calcular o preço de liquidação."],"faq":[{"q":"Robô de grid dá lucro sempre?","a":"Não. Ele lucra com a oscilação dentro da faixa, mas pode ter prejuízo se o preço cair e ficar abaixo do mínimo, já que você termina com mais do ativo desvalorizado."},{"q":"Qual a melhor configuração de grid?","a":"Não há uma única. Faixas mais largas aguentam mais movimento, e espaçamento maior reduz o peso das taxas. Teste com valores pequenos antes."}],"title":"O que é robô de grid? Grid trading em cripto","description":"Aprenda como um robô de grid compra e vende em faixas de preço, quando ele funciona e o que acontece se o preço sair.","related":[["dollar-cost-averaging","Preço médio (DCA)","DCA (dollar-cost averaging) é a estratégia de comprar um valor fixo de um ativo em intervalos regulares, independentemente do preço, para diluir o custo médio ao longo do tempo."],["copy-trading","Copy trading","Copy trading é um recurso em que você conecta parte do seu saldo a um trader escolhido e a plataforma replica automaticamente as operações dele na sua conta, de forma proporcional ao valor alocado."],["volatility","Volatilidade","Volatilidade é a intensidade e a frequência com que o preço de um ativo sobe e desce num período; quanto maior, mais amplos e rápidos são os movimentos."],["limit-order","Ordem limitada","Ordem limitada é a instrução para comprar ou vender apenas a um preço definido por você ou melhor, ficando registrada no livro de ofertas até ser executada ou cancelada."]],"lesson":null,"coin":null,"tool":null,"cta":true}});
